MERGE `{{params.project_name}}.semantics_central.FinancingContracts` final
USING (
{{range_query}}
) staging
ON final.contract_id = staging.contract_id
WHEN MATCHED THEN
UPDATE SET
final.contract_id = staging.contract_id,
final.financing_customer_id = staging.financing_customer_id,
final.limits = staging.limits,
final.fees = staging.fees,
final.status = staging.status,
final.repayment_days = staging.repayment_days,
final.created_at = staging.created_at,
final.updated_at = staging.updated_at,
final.deleted_at = staging.deleted_at,
final.created_by_name = staging.created_by_name,
final.created_by_id = staging.created_by_id,
final.updated_by_name = staging.updated_by_name,
final.updated_by_id = staging.updated_by_id,
final.deleted_by_name = staging.deleted_by_name,
final.deleted_by_id = staging.deleted_by_id,
final.min_loan_amount = staging.min_loan_amount,
final.min_loan_amount_usd = staging.min_loan_amount_usd,
final.max_loan_amount = staging.max_loan_amount,
final.max_loan_amount_usd = staging.max_loan_amount_usd,
final.down_payment = staging.down_payment,
final.down_payment_usd = staging.down_payment_usd,
final.security_deposit = staging.security_deposit,
final.security_deposit_usd = staging.security_deposit_usd,
final.country_id = staging.country_id
WHEN NOT MATCHED THEN
INSERT (
contract_id,
financing_customer_id,
limits,
fees,
status,
repayment_days,
created_at,
updated_at,
deleted_at,
created_by_name,
created_by_id,
updated_by_name,
updated_by_id,
deleted_by_name,
deleted_by_id,
min_loan_amount,
min_loan_amount_usd,
max_loan_amount,
max_loan_amount_usd,
down_payment,
down_payment_usd,
security_deposit,
security_deposit_usd,
country_id
) VALUES (
staging.contract_id,
staging.financing_customer_id,
staging.limits,
staging.fees,
staging.status,
staging.repayment_days,
staging.created_at,
staging.updated_at,
staging.deleted_at,
staging.created_by_name,
staging.created_by_id,
staging.updated_by_name,
staging.updated_by_id,
staging.deleted_by_name,
staging.deleted_by_id,
staging.min_loan_amount,
staging.min_loan_amount_usd,
staging.max_loan_amount,
staging.max_loan_amount_usd,
staging.down_payment,
staging.down_payment_usd,
staging.security_deposit,
staging.security_deposit_usd,
staging.country_id
)